"""
ivw_sap_service.py - SAP-spezifische IVW-Logik: Parsen von SAP-Dateien und SAP-Ansicht.

Fachlicher Hintergrund
----------------------
Für Print-Titel meldet das SAP-System Mengen, die NICHT aus unserem
eSuite-Fulfilment kommen - typischerweise:

- **Remissionen**: an die Druckerei zurückgegangene, unverkaufte Exemplare.
- **Werbestücke / Belegexemplare / Freistücke**: kostenfreie Ausgaben
  an Vertrieb, Kunden, Archive.
- **Archivstücke, Reststücke, EV-Lieferungen**: diverse Sonderfälle.

Diese Mengen müssen in die IVW-Meldung einfließen, damit die Gesamtzahlen
(Druckauflage, verbreitete Auflage, Verkauf) stimmen.

Dateiformat
-----------
Das SAP-System exportiert ein textbasiertes Layout (CP1252-kodiert) mit
einem Kopfbereich (Druckerzeugnis, PVA, Zeitraum, Anzahl Erscheinungen)
und einer Pipe-getrennten tabelle (Meldekategorie, Typ, Gesamtmenge,
DS-Menge).

Vorzeichen-Konvention
---------------------
Remissionen reduzieren die verbreitete Auflage. SAP liefert diese Mengen
aber als positive Zahl. Damit sie korrekt als Abzug in die Summe einfließen,
werden sie hier grundsätzlich auf ein negatives Vorzeichen gesetzt
(siehe _parse_table_data).

Verwendung
----------
    from core_services.ivw.ivw_sap_service import (
        parse_sap_file_to_df, parse_sap_folder, _create_sap_view
    )
"""

import logging
import re
from pathlib import Path
from typing import Any

import pandas as pd

from ..db.client import connect_to_db
from ..db.import_service import save_df_to_db
from ..utils.progress_logging import iter_with_progress

logger = logging.getLogger(__name__)

# ============================================================
# HELPER-FUNKTIONEN SAP-datei PARSEN (PRIVATE)
# ============================================================


def _extract_header_info(lines: list[str]) -> dict[str, Any]:
    """Liest den Kopf einer SAP-Exportdatei aus.

    Gesucht werden in den ersten 30 Zeilen einer Sektion:

    - "Druckerzeugnis"          -> Kürzel und Name des Titels
    - "Planvertriebsausgabe"    -> PVA-Nummer und PVA-Name
    - "Versand-/Remissions-
       zeitraum"                -> Zeitraum von - bis und Anzahl
                                   Erscheinungstage (Anzahl VA)

    Jede Info wird mit einem Regulären Ausdruck (Regex) aus der Textzeile
    herausgeschnitten. Wird ein Feld nicht gefunden, wird eine Warnung
    geloggt und das Feld bleibt leer - die Sektion wird später wegen
    fehlender Header-Info verworfen.
    """
    header_info: dict[str, Any] = {}

    logger.debug("=== Erste 30 Zeilen der Sektion ===")
    for i, line in enumerate(lines[:30]):
        logger.debug(f"Zeile {i}: {line[:100]}")

    for line in lines[:30]:
        if "Druckerzeugnis" in line and "Druckerzeugnis_Kuerzel" not in header_info:
            match = re.search(r"Druckerzeugnis\s+([\w-]+)\s+(.+?)(?:\s{2,}|$)", line)
            if match:
                header_info["Druckerzeugnis_Kuerzel"] = match.group(1).strip()
                header_info["Druckerzeugnis_Name"] = re.split(r"\s{3,}", match.group(2).strip())[0]
            else:
                logger.warning(f"Regex-Match fehlgeschlagen für: {line[:80]}")

        if "Planvertriebsausgabe" in line and "PVA_Nummer" not in header_info:
            match = re.search(r"Planvertriebsausgabe\s+([\w-]+(?:\s+[\w-]+)?)\s+(.+?)(?=\s{3,}|$)", line)
            if match:
                header_info["PVA_Nummer"] = match.group(1).strip()
                header_info["PVA_Name"] = re.split(r"\s{3,}", match.group(2).strip())[0]
            else:
                logger.warning(f"Regex-Match fehlgeschlagen für: {line[:80]}")

        if "Versand-/Remissionszeitraum" in line and "Zeitraum_Von" not in header_info:
            match = re.search(r"(\d{2}\.\d{2}\.\d{4})\s*-\s*(\d{2}\.\d{2}\.\d{4})", line)
            if match:
                header_info["Zeitraum_Von"] = pd.to_datetime(match.group(1), format="%d.%m.%Y")
                header_info["Zeitraum_Bis"] = pd.to_datetime(match.group(2), format="%d.%m.%Y")

            match_va = re.search(r"Anzahl VA\s+(\d+)", line)
            if match_va:
                header_info["Anzahl_VA"] = int(match_va.group(1))

    logger.debug(f"Header-Info komplett: {header_info}")
    return header_info


def _parse_table_data(lines: list[str], header_info: dict[str, Any]) -> list[dict[str, Any]]:
    """Liest die Mengentabelle einer SAP-Sektion aus.

    Eine SAP-Tabellenzeile sieht etwa so aus:

        | Remissionen | (Typ) | 1.234 | 12,5- |

    Pro Zeile werden vier Werte übernommen:

    - **Meldekategorie** (z.B. "Remissionen", "Werbestücke"): bestimmt
      die IVW-Zeile.
    - **Typ** (optional).
    - **Gesamtmenge**: Gesamtauflage im Zeitraum. Zahlenformat deutsch
      (1.234,56) wird in englisches Format (1234.56) umgewandelt.
    - **DS-Menge** (Durchschnittsschnitt): Zahlen mit nachgestelltem
      Minus ("12,5-") sind negative Werte - SAP-Konvention.

    Vorzeichen-Regel für Remissionen und körperlose Remi:
    Beide reduzieren die Auflage und werden deshalb zwangsweise auf
    einen negativen Wert gesetzt, unabhängig vom Vorzeichen in der datei.
    """
    if not header_info:
        logger.warning("Keine Header-Info vorhanden, überspringe Sektion")
        return []

    records: list[dict[str, Any]] = []
    in_table = False

    for line_num, line in enumerate(lines):
        if "|Meldekategorie" in line:
            in_table = True
            logger.debug(f"Tabellenstart erkannt in Zeile {line_num}")
            continue

        if line.strip().startswith("---") and line.strip().endswith("---"):
            continue

        if in_table and line.strip().startswith("|") and "Meldekategorie" not in line:
            parts = [p.strip() for p in line.split("|")[1:-1]]

            if len(parts) >= 3:
                kategorie = parts[0].strip()
                typ = parts[1].strip() if len(parts) > 1 else ""

                if kategorie.startswith("---") or not kategorie or kategorie == "Meldekategorie":
                    continue

                # Gesamtmenge einlesen: deutsche Zahl "1.234" -> 1234.
                gesamtmenge_str = parts[2].strip().replace(".", "").replace(",", ".")
                try:
                    gesamtmenge = int(gesamtmenge_str)
                    # Remissionen sind Abzüge -> Vorzeichen erzwingen.
                    if "Remissionen" in kategorie or "körperlose Remi" in kategorie:
                        gesamtmenge = -abs(gesamtmenge)
                except Exception:
                    gesamtmenge = 0

                # DS-Menge einlesen. Nachgestelltes Minus ("12,5-") ist
                # SAP-Konvention für negative Zahlen.
                ds_menge_str = parts[3].strip() if len(parts) > 3 else "0"
                if ds_menge_str.endswith("-"):
                    try:
                        ds_menge = -float(ds_menge_str[:-1].strip().replace(".", "").replace(",", "."))
                    except Exception:
                        ds_menge = 0
                else:
                    try:
                        ds_menge = float(ds_menge_str.replace(".", "").replace(",", "."))
                    except Exception:
                        ds_menge = 0

                # Auch hier: Remissionen immer als negativer DS.
                if "Remissionen" in kategorie or "körperlose Remi" in kategorie:
                    ds_menge = -abs(ds_menge)

                records.append(
                    {
                        **header_info,
                        "Meldekategorie": kategorie,
                        "Typ": typ,
                        "Gesamtmenge": gesamtmenge,
                        "DS_Menge": ds_menge,
                    }
                )

    logger.debug(f"Sektion abgeschlossen: {len(records)} Datensätze hinzugefügt")
    return records


def _parse_file_content(content: str) -> list[dict[str, Any]]:
    """Parst den Inhalt einer SAP-datei und gibt alle Datensätze zurück."""
    all_records: list[dict[str, Any]] = []
    sections = re.split(r"Hierarchietyp\s+\d+", content)

    sections_to_process = sections[1:]
    for section in iter_with_progress(logger, sections_to_process, len(sections_to_process), "SAP-Sektionen"):
        lines = section.split("\n")
        header_info = _extract_header_info(lines)
        records = _parse_table_data(lines, header_info)
        all_records.extend(records)

    return all_records


def _read_sap_file(filepath: str | Path) -> str:
    """Liest eine SAP-datei (CP1252-kodiert) und gibt den Inhalt zurück."""
    with open(filepath, encoding="cp1252") as f:
        return f.read()


def _process_files_in_folder(folder_path: str | Path) -> pd.DataFrame | None:
    """Verarbeitet alle .txt-Dateien in einem Ordner und gibt kombinierten DataFrame zurück."""
    folder = Path(folder_path)

    if not folder.is_dir():
        logger.error(f"'{folder_path}' ist kein Ordner")
        return None

    files = [f for f in folder.iterdir() if f.is_file() and f.suffix.lower() == ".txt"]

    if not files:
        logger.warning(f"Keine .txt-Dateien im Ordner '{folder_path}' gefunden")
        return None

    logger.info(f"{len(files)} datei(en) im Ordner gefunden")

    all_dataframes = []
    for idx, file in iter_with_progress(logger, enumerate(files, 1), len(files), "SAP-Dateien"):
        logger.info(f"Parse datei {idx}/{len(files)}: {file.name}")
        try:
            df = parse_sap_file_to_df(file)
            if df is not None and not df.empty:
                all_dataframes.append(df)
                logger.info(f"  → {len(df)} Zeilen geparst")
            else:
                logger.warning("  → Keine Daten gefunden")
        except Exception as e:
            logger.error(f"Fehler bei datei {file.name}: {e}", exc_info=True)

    if not all_dataframes:
        logger.error("Keine Daten aus den Dateien extrahiert")
        return None

    combined_df = pd.concat(all_dataframes, ignore_index=True)
    logger.info(f"Gesamt: {len(combined_df)} Zeilen aus {len(all_dataframes)} Dateien")
    return combined_df


# ============================================================
# SAP-ANSICHT FÜR IVW-ORCHESTRATOR
# ============================================================


def _create_sap_view(start_date: str, end_date: str, art_in: str, welt_in: str) -> pd.DataFrame:
    """Baut die SAP-Zeilen für die IVW-Gesamtauswertung.

    Filtert die SAP-Auflagenmeldungen auf jene Kategorien, die zusätzlich
    zu den eSuite-Fulfilments in die IVW einfließen müssen
    (Werbestücke, Remissionen, Reststücke etc.) und ordnet jeder Zeile
    einen Erscheinungs-Rhythmus zu:

        1 Erscheinung pro Woche  -> vermutlich Samstag       -> "Sa"
        5 Erscheinungen pro Woche -> Mo-Fr                    -> "Mo-Fr"
        6 Erscheinungen pro Woche -> Mo-Sa                    -> "Mo-Sa"

    Die Zuordnung passiert über DENSE_RANK: diejenige PVA mit den meisten
    Anzahl_VA-Werten bekommt "Mo-Sa", die nächste "Mo-Fr", die kleinste
    "Sa". Grundlage sind ausschließlich Print-PVAs, weil SAP-Auflagen
    nur für Print relevant sind.
    """
    logger.info("Erstelle SAP-Ansicht mit IVW Daten...")

    conn = connect_to_db()
    if not conn:
        logger.error("Keine Datenbankverbindung hergestellt!")
        return pd.DataFrame()
    try:
        cursor = conn.cursor()

        query = f"""
        SELECT
            'Print' AS Art,
            sap.PVA_Nummer AS PVA,
            pva.Gesamt_SAP AS Gesamt_PVA,
            pva.bezeichnung AS Bezeichnung,
            pva.Welt,
            pva.objekt AS Objekt,
            map.IVWCategory AS IVWKategorie,
            map.Meldung AS Meldekategorie,
            map.Verkauf,
            map.Verbreitung,
            map.Druckauflage,
            CASE
                WHEN zuord.days = 1 THEN 'Mo-Sa'
                WHEN zuord.days = 2 THEN 'Mo-Fr'
                WHEN zuord.days = 3 THEN 'Sa'
            END AS Erscheinung,
            sap.Anzahl_VA AS ANZAHL_ET,
            sap.Gesamtmenge,
            sap.DS_Menge AS DS,
            'SAP' AS Quelle,
            sap.Zeitraum_Von AS Zeitraum_von,
            sap.Zeitraum_Bis AS Zeitraum_bis
        FROM tb_ivw_sap_auflagen sap
            LEFT JOIN tb_mapping_pva pva ON sap.PVA_Nummer = pva.SAP
            LEFT JOIN tb_ivw_mapping_ivwcategory map ON map.IVWCategory_esuite = sap.Meldekategorie
            LEFT JOIN (
                SELECT Anzahl_VA, DENSE_RANK() OVER (ORDER BY Anzahl_VA DESC) AS days
                FROM tb_ivw_sap_auflagen
                WHERE Zeitraum_von = %s AND Zeitraum_bis = %s
                GROUP BY Anzahl_VA
            ) zuord ON zuord.Anzahl_VA = sap.Anzahl_VA
        WHERE sap.Meldekategorie IN (
                'Archivstücke', 'Belegexemplare', 'Rchn. Restaufl.',
                'Reststücke', 'Sonstg. Freist.', 'Werbestücke',
                'Zust.-Pers.-St.', 'EV Lieferungen', 'körperlose Remi', 'Remissionen'
            )
            AND pva.Art = 'Print'
            AND sap.Zeitraum_von = %s AND sap.Zeitraum_bis = %s
            AND pva.Art IN ({art_in})
            AND pva.Welt IN ({welt_in})
        GROUP BY
            sap.PVA_Nummer, pva.bezeichnung, pva.Welt, pva.objekt, sap.Meldekategorie,
            map.Meldung, map.Verkauf, map.Verbreitung, map.Druckauflage,
            zuord.days, sap.Anzahl_VA, sap.Gesamtmenge, sap.DS_Menge,
            sap.Zeitraum_Von, sap.Zeitraum_Bis
        """

        cursor.execute(query, (start_date, end_date, start_date, end_date))
        rows = cursor.fetchall()
        columns = [desc[0] for desc in cursor.description]
        result = pd.DataFrame(rows, columns=columns)

        if not result.empty:
            result["Zeitraum_von"] = pd.to_datetime(start_date).strftime("%d.%m.%Y")
            result["Zeitraum_bis"] = pd.to_datetime(end_date).strftime("%d.%m.%Y")
            column_order = [
                "Art",
                "PVA",
                "Gesamt_PVA",
                "Bezeichnung",
                "Welt",
                "Objekt",
                "IVWKategorie",
                "Meldekategorie",
                "Verkauf",
                "Verbreitung",
                "Druckauflage",
                "Erscheinung",
                "ANZAHL_ET",
                "Gesamtmenge",
                "DS",
                "Quelle",
                "Zeitraum_von",
                "Zeitraum_bis",
            ]
            result = result[column_order]

        cursor.close()
        return result
    finally:
        conn.close()


# ============================================================
# HAUPTFUNKTIONEN
# ============================================================


def parse_sap_file_to_df(filepath: str | Path) -> pd.DataFrame:
    """Parst eine SAP-Ausgabedatei und gibt einen DataFrame zurück.

    Args:
        filepath: Pfad zur SAP-Ausgabedatei (str oder Path).

    Returns:
        DataFrame mit den extrahierten Daten.
    """
    content = _read_sap_file(filepath)
    all_records = _parse_file_content(content)
    logger.info(f"Gesamt: {len(all_records)} Datensätze geparst")
    return pd.DataFrame(all_records)


def parse_sap_folder(folder_path: str | Path, target_table: str, truncate_table: str) -> bool:
    """Verarbeitet alle SAP-Dateien in einem Ordner und importiert sie in die Datenbank.

    Args:
        folder_path: Pfad zum Ordner mit SAP-Ausgabedateien.
        target_table: Zieltabelle in der Datenbank.
        truncate_table: 'Ja' um tabelle zu leeren, sonst 'Nein'.

    Returns:
        True bei Erfolg, False bei Fehler.
    """
    combined_df = _process_files_in_folder(folder_path)
    if combined_df is None or combined_df.empty:
        return False
    try:
        save_df_to_db(combined_df, target_table, truncate_table)
        return True
    except Exception:
        return False
